const $=s=>document.querySelector(s);
const KEY='em-dia-v1';
const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cents=n=>Math.round(Number(n)*100);
const total=l=>l.agreedTotal??(l.principal+Math.round(l.principal*l.interest/100));
const paid=l=>l.payments.reduce((sum,p)=>sum+p.amount,0);
const balance=l=>Math.max(0,total(l)-paid(l));
const days=(a,b)=>Math.max(0,Math.floor((Date.parse(b+'T00:00:00Z')-Date.parse(a+'T00:00:00Z'))/86400000));
const date=s=>s.split('-').reverse().join('/');
let loans=[],storageOK=true,lastEdited='rate';
function message(text){$('#message').textContent=text;}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||data.some(l=>!l||typeof l.name!=='string'||typeof l.id!=='string'||!Number.isSafeInteger(l.principal)||l.principal<=0||!Number.isFinite(l.interest)||!/^\d{4}-\d{2}-\d{2}$/.test(l.start)||!/^\d{4}-\d{2}-\d{2}$/.test(l.due)||!Array.isArray(l.payments)||l.payments.some(p=>!Number.isSafeInteger(p.amount)||p.amount<0)||(l.agreedTotal!==undefined&&!Number.isSafeInteger(l.agreedTotal))))throw Error();loans=data;}}catch{storageOK=false;message('Não foi possível carregar seus registros. Os dados existentes foram preservados.');}
function save(next){if(!storageOK){message('Não é possível salvar enquanto os registros existentes não puderem ser carregados.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));loans=next;render();return true;}catch{message('Não foi possível salvar. Verifique se o navegador permite armazenamento local.');return false;}}
function calculate(source){if(source==='receivable'||source==='rate')lastEdited=source;const p=cents($('#principal').value);$('#receivable').setCustomValidity('');if(!p||p<=0){if(source==='principal')$('#'+(lastEdited==='rate'?'receivable':'rate')).value='';return;}if(lastEdited==='receivable'){const value=$('#receivable').value;if(value===''){$('#rate').value='';return;}const t=cents(value);$('#rate').value=Number(((t-p)/p*100).toFixed(6));if(t<p)$('#receivable').setCustomValidity('O valor a receber deve ser igual ou maior que o emprestado.');}else{const r=$('#rate').value;if(r===''){$('#receivable').value='';return;}const rate=Number(r);$('#receivable').value=((p+Math.round(p*rate/100))/100).toFixed(2);}}
['principal','receivable','rate'].forEach(id=>$('#'+id).addEventListener('input',()=>calculate(id)));
$('#form').addEventListener('submit',e=>{e.preventDefault();calculate('submit');const name=$('#name').value.trim(),principal=cents($('#principal').value),agreedTotal=cents($('#receivable').value),due=$('#due').value;if(!name){message('Informe o nome.');$('#name').focus();return;}if(!$('#form').reportValidity()||!Number.isSafeInteger(principal)||principal<=0||!Number.isSafeInteger(agreedTotal)||agreedTotal<principal)return;const loan={id:crypto.randomUUID(),name,principal,agreedTotal,interest:(agreedTotal-principal)/principal*100,start:today(),due,phone:'',notes:'',payments:[]};if(save([...loans,loan])){e.target.reset();lastEdited='rate';message('Empréstimo adicionado.');$('#name').focus();}});
function render(){const open=loans.filter(l=>balance(l)>0);$('#total-lent').textContent=money(loans.reduce((s,l)=>s+l.principal,0));$('#total-due').textContent=money(loans.reduce((s,l)=>s+balance(l),0));$('#open-count').textContent=open.length;$('#empty').hidden=loans.length>0;$('#list').innerHTML=[...loans].sort((a,b)=>(balance(a)===0)-(balance(b)===0)||a.due.localeCompare(b.due)).map(l=>{const remaining=balance(l),late=remaining>0&&l.due<today();const end=remaining>0?today():(l.payments.map(p=>p.date).sort().at(-1)||today());return `<article class="loan"><div><div class="loan-name">${esc(l.name)}</div><small>${money(l.principal)} emprestados · ${Number(l.interest.toFixed(2)).toLocaleString('pt-BR')}%</small></div><div><span class="amount">${money(remaining)}</span><small>${remaining?'a receber':'recebido: '+money(paid(l))}</small></div><div><span class="time">${days(l.start,end)} dia(s) emprestado</span><small class="${late?'overdue':''}">${remaining?(late?'Venceu em ':'Receber em '):'Vencimento: '}${date(l.due)}</small></div><div>${remaining?`<button data-receive="${esc(l.id)}">Marcar recebido</button>`:`<span class="settled">Recebido</span>${l.payments.some(p=>p.quickSettlement)?`<br><button class="undo" data-undo="${esc(l.id)}">Desfazer</button>`:''}`}</div></article>`;}).join('');}
$('#list').addEventListener('click',e=>{const receive=e.target.closest('[data-receive]'),undo=e.target.closest('[data-undo]');if(receive){const l=loans.find(x=>x.id===receive.dataset.receive);if(l&&save(loans.map(x=>x.id===l.id?{...x,payments:[...x.payments,{amount:balance(x),date:today(),quickSettlement:true}]}:x)))message('Recebimento registrado. Você pode desfazer na lista.');}if(undo){if(save(loans.map(x=>x.id===undo.dataset.undo?{...x,payments:x.payments.filter(p=>!p.quickSettlement)}:x)))message('Recebimento desfeito.');}});
render();setInterval(render,60000);
